# Test mod 5 mapping
mapper = {0:2, 1:2, 2:4, 3:3, 4:3}  
def output_mod5(col):
    return mapper.get(col % 5, 3)

print("Testing mod 5 mapping:")
for col, out, r in demo_data:
    pred = output_mod5(col)
    status = "OK" if pred == out else "FAIL"
    if pred != out:
